{
  "mushroom": "Amanita phalloides (death cap)",
  "composition": [
    {
      "compound": "α-Amanitin",
      "amount": "~3% of dry weight",
      "effect": "Inhibits RNA polymerase II in liver and kidney cells, halting protein synthesis and causing cell death."
    },
    {
      "compound": "β-Amanitin",
      "amount": "~1% of dry weight",
      "effect": "Inhibits RNA polymerase II with slightly lower affinity than α-amanitin, contributing to hepatotoxicity."
    },
    {
      "compound": "γ-Amanitin",
      "amount": "~0.5% of dry weight",
      "effect": "Inhibits RNA polymerase II with lower potency than α-amanitin and adds to the overall toxic load."
    },
    {
      "compound": "ε-Amanitin",
      "amount": "unknown",
      "effect": "A minor cyclic peptide with weak RNA polymerase II inhibitory activity that contributes marginally to amatoxin toxicity."
    },
    {
      "compound": "α-Phalloidin",
      "amount": "~2% of dry weight",
      "effect": "Binds actin filaments and alters membrane permeability in smooth-muscle and kidney cells, causing diarrhoea and vascular effects."
    },
    {
      "compound": "β-Phalloidin",
      "amount": "~0.5% of dry weight",
      "effect": "Acts similarly to α-phalloidin but with lower binding affinity for actin, contributing to smooth-muscle disruption."
    },
    {
      "compound": "Vescatoxins",
      "amount": "unknown",
      "effect": "Low-molecular-weight cyclic peptides with modest toxicity that add to the overall phalloid/amanitin toxic profile."
    }
  ]
}

{
