    {
      "compound": "Proteins and free amino acids",
      "amount": "~3–5 % of fresh weight",
      "effect": "Provide essential amino acids for tissue repair and enzyme synthesis."
    },
    {
      "compound": "Ergosterol / Vitamin D₂",
      "amount": "~5–15 mg per 100 g dry weight",
      "effect": "Supports calcium absorption and bone metabolism in humans."
    },
    {
      "compound": "Biotin (Vitamin B₇)",
      "amount": "~20–40 µg per 100 g fresh weight",
      "effect": "Acts as a coenzyme in fatty-acid synthesis and gluconeogenesis."
    },
    {
      "compound": "Carotenoid pigments (e.g., canthaxanthin-like compounds)",
      "amount": "unknown",
      "effect": "Exhibit antioxidant activity and contribute to the characteristic orange colour of the cap."
