    {
      "compound": "Minerals (K, P, Na, Ca, Fe, Zn)",
      "amount": "~200–500 mg/kg dry weight (varies by element)",
      "effect": "Maintain electrolyte balance, support enzymatic reactions, and contribute to structural and metabolic functions."
    }
  ]
}
